import{_ as i,o as e,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2015-SEP-24 -- Ceph Tech Talks: Reference Architectures","description":"","frontmatter":{"title":"2015-SEP-24 -- Ceph Tech Talks: Reference Architectures","date":"2015-09-24T00:00:00.000Z","updated":"2015-09-25T00:00:00.000Z","tags":["Ceph","分布式存储","参考架构","性能优化","存储设计"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/2015-SEP-24_--_Ceph_Tech_Talks_-_Reference_Architectures.md","filePath":"posts/2015/2015-SEP-24_--_Ceph_Tech_Talks_-_Reference_Architectures.md","lastUpdated":1780459816000}'),s={name:"posts/2015/2015-SEP-24_--_Ceph_Tech_Talks_-_Reference_Architectures.md"};function o(p,l,n,a,_,c){return e(),t("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2015年9月24日</p><p><strong>会议主题</strong>： 构建Ceph参考架构</p><p><strong>参会人员</strong>： Brent Compton, Kyle Vader, Patrick等</p><p><strong>会议内容</strong>：</p><p><strong>一、会议背景</strong></p><p>本次会议主要讨论了如何构建Ceph参考架构，并分享了构建过程中的关键考虑因素和设计要点。</p><p><strong>二、讨论的主要议题</strong></p><ol><li><p><strong>构建参考架构的目的</strong>：</p><ul><li>基于实证数据而非传闻回答客户关于软件定义存储的问题。</li><li>在合作伙伴实验室进行各种基准测试和负载测试，以获取数据来支持问题解答。</li></ul></li><li><p><strong>参考架构的构建模块</strong>：</p><ul><li>分布式存储：网络是基础模块，10G以太网和40G以太网的使用对性能有显著影响。</li><li>存储服务器：近年来，基于x86的服务器类型和容量发生了爆炸式增长。</li></ul></li><li><p><strong>参考架构的类型</strong>：</p><ul><li>基础架构：如性能和尺寸指南。</li><li>集成指南：如Red Hat Enterprise Linux OpenStack平台参考架构。</li></ul></li><li><p><strong>构建参考架构的考虑因素</strong>：</p><ul><li>扩展存储的需求</li><li>设计工作负载I/O</li><li>存储访问方法</li><li>识别容量</li><li>数据保护方案</li><li>服务器故障域</li></ul></li><li><p><strong>4x3矩阵</strong>：</p><ul><li>用于识别针对不同工作负载I/O类别的候选架构。</li><li>包括IOPS优化、吞吐量优化、成本容量优化、读/写混合、纠错编码池与复制池等。</li></ul></li><li><p><strong>性能和尺寸指南</strong>：</p><ul><li>主要关注性能和尺寸优化。</li><li>使用Rados、Fio和CIS基准测试工具进行测试。</li><li>发布了与Supermicro、Cisco和Scalable Informatics合作发布的性能和尺寸指南。</li></ul></li><li><p><strong>社区资源</strong>：</p><ul><li>构建社区资源，如性能基准测试库和集群组成统计信息。</li><li>通过metric.se.com提供交互式格式。</li></ul></li></ol><p><strong>三、决定的事项</strong></p><ol><li>继续关注性能和尺寸优化，并发布更多性能和尺寸指南。</li><li>建立社区资源，如性能基准测试库和集群组成统计信息。</li><li>与MySQL MariaDB社区合作，构建更高级的参考架构。</li></ol><p><strong>四、后续行动计划</strong></p><ol><li>发布更多性能和尺寸指南。</li><li>建立社区资源，如性能基准测试库和集群组成统计信息。</li><li>与MySQL MariaDB社区合作，构建更高级的参考架构。</li><li>收集社区反馈，改进参考架构和社区资源。</li></ol><p><strong>五、关键词</strong></p><ul><li>Ceph</li><li>分布式存储</li><li>网络带宽</li><li>存储服务器</li><li>扩展存储</li><li>工作负载I/O</li><li>存储访问方法</li><li>容量</li><li>数据保护方案</li><li>服务器故障域</li><li>性能和尺寸优化</li><li>基准测试</li><li>社区资源</li></ul>',15)])])}const h=i(s,[["render",o]]);export{u as __pageData,h as default};
